IF EXISTS(SELECT 1 FROM @Baseline b LEFT JOIN sys.objects o ON o.name=b.Name AND o.schema_id=SCHEMA_ID(N'dbo') LEFT JOIN sys.sql_modules m ON m.object_id=o.object_id
    WHERE m.definition IS NULL OR CONVERT(VARCHAR(64),HASHBYTES('SHA2_256',TRIM(NCHAR(9)+NCHAR(10)+N' ' FROM REPLACE(m.definition,NCHAR(13),N''))),2)<>b.Expected_Hash)
BEGIN
    SELECT b.Name FROM @Baseline b LEFT JOIN sys.objects o ON o.name=b.Name AND o.schema_id=SCHEMA_ID(N'dbo') LEFT JOIN sys.sql_modules m ON m.object_id=o.object_id
    WHERE m.definition IS NULL OR CONVERT(VARCHAR(64),HASHBYTES('SHA2_256',TRIM(NCHAR(9)+NCHAR(10)+N' ' FROM REPLACE(m.definition,NCHAR(13),N''))),2)<>b.Expected_Hash;
    THROW 51598,N'Inventory SQL đã thay đổi so với baseline. Cần review lại trước khi deploy.',1;
END;
IF NOT EXISTS(SELECT 1 FROM sys.indexes i JOIN sys.index_columns ic ON ic.object_id=i.object_id AND ic.index_id=i.index_id AND ic.key_ordinal=1
    JOIN sys.columns c ON c.object_id=ic.object_id AND c.column_id=ic.column_id
    WHERE i.object_id=OBJECT_ID(N'dbo.tbl_XNK_Nhap_Kho') AND i.name=N'UX_tbl_XNK_Nhap_Kho_So_Phieu' AND i.is_unique=1 AND i.is_disabled=0 AND i.has_filter=0
        AND c.name=N'So_Phieu_Nhap_Kho' AND NOT EXISTS(SELECT 1 FROM sys.index_columns extra WHERE extra.object_id=i.object_id AND extra.index_id=i.index_id AND extra.key_ordinal>1))
 OR NOT EXISTS(SELECT 1 FROM sys.indexes i JOIN sys.index_columns ic ON ic.object_id=i.object_id AND ic.index_id=i.index_id AND ic.key_ordinal=1
    JOIN sys.columns c ON c.object_id=ic.object_id AND c.column_id=ic.column_id
    WHERE i.object_id=OBJECT_ID(N'dbo.tbl_XNK_Xuat_Kho') AND i.name=N'UX_tbl_XNK_Xuat_Kho_So_Phieu' AND i.is_unique=1 AND i.is_disabled=0 AND i.has_filter=0
        AND c.name=N'So_Phieu_Xuat_Kho' AND NOT EXISTS(SELECT 1 FROM sys.index_columns extra WHERE extra.object_id=i.object_id AND extra.index_id=i.index_id AND extra.key_ordinal>1))
    THROW 51598,N'Thiếu unique index số phiếu bắt buộc.',1;
